-- Seed: catalogue expansion — every social network, Instagram share/save/reach/live, AI subscriptions.
-- Idempotent. Prices are toman per single unit (an order is charged quantity × unit price);
-- the app lists them per 1000 (per 100 for comments / watch hours, per month for AI plans).
-- DRAFT PRICES: confirm with the owner before running against production.

BEGIN;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, active = true;

ON CONFLICT (product_id, slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, service_type = EXCLUDED.service_type, active = true;

ON CONFLICT (service_id, parameter_key) DO UPDATE SET schema = EXCLUDED.schema;

-- One active IRT price per service; replaces the previous active row's amount and bounds in place.
ON CONFLICT (service_id, currency) WHERE active = true DO UPDATE SET
  unit_price_minor = EXCLUDED.unit_price_minor, min_quantity = EXCLUDED.min_quantity, max_quantity = EXCLUDED.max_quantity,
  price_version = service_prices.price_version + 1, price_updated_at = now();

COMMIT;
